// Difference Chart — Basic, route: jsx
// Source: difference-chart_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo, useId } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from difference ----
type DifferencePoint_difference = { date: Date; sanFrancisco: number; newYork: number };

const DAYS = 365;

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const seasonal = (day: number, peakDay: number) =>
  Math.cos((2 * Math.PI * (day - peakDay)) / DAYS);

const random = seededRandom(20260813);

/**
 * Synthetic daily highs: San Francisco is mild year round, New York swings hard,
 * so the two series cross repeatedly through spring and autumn.
 */
const cityTemperatures: DifferencePoint_difference[] = (() => {
  let sfDrift = 0;
  let nyDrift = 0;
  return Array.from({ length: DAYS }, (_, day) => {
    // Carrying drift forward makes the weather correlated day to day instead of jittery.
    sfDrift = sfDrift * 0.7 + (random() - 0.5) * 3.6;
    nyDrift = nyDrift * 0.78 + (random() - 0.5) * 7.5;
    return {
      date: new Date(Date.UTC(2024, 0, 1 + day)),
      sanFrancisco: 57 + 5 * seasonal(day, 262) + sfDrift,
      newYork: 55 + 24 * seasonal(day, 201) + nyDrift
    };
  });
})();

/** Two series sampled on the same dates; the shaded band is the gap between them. */
export type Data = { date: Date; sanFrancisco: number; newYork: number }[];

type DifferencePoint = Data[number];

const MARGIN = { top: 28, right: 20, bottom: 36, left: 52 };
const WARMER = d3.schemeRdYlBu[3][0]; // San Francisco above New York
const COOLER = d3.schemeRdYlBu[3][2];

export default function DifferenceChart({
  data = cityTemperatures,
  width
}: {
  data?: Data;
  width: number;
}) {
  const clipId = useId();
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleTime()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([
          d3.min(data, (d) => Math.min(d.sanFrancisco, d.newYork)) ?? 0,
          d3.max(data, (d) => Math.max(d.sanFrancisco, d.newYork)) ?? 0
        ])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  // Four step areas share one generator; only the baseline and the traced series change.
  const areaTo = useMemo(() => {
    const build = (baseline: number, value: (d: DifferencePoint) => number) =>
      d3
        .area<DifferencePoint>()
        .curve(d3.curveStep)
        .x((d) => x(d.date))
        .y0(baseline)
        .y1((d) => y(value(d)))(data) ?? '';
    return {
      aboveNewYork: build(0, (d) => d.newYork),
      belowNewYork: build(innerHeight, (d) => d.newYork),
      aboveSanFrancisco: build(0, (d) => d.sanFrancisco),
      belowSanFrancisco: build(innerHeight, (d) => d.sanFrancisco)
    };
  }, [data, x, y, innerHeight]);

  const line = useMemo(
    () =>
      d3
        .line<DifferencePoint>()
        .curve(d3.curveStep)
        .x((d) => x(d.date))
        .y((d) => y(d.sanFrancisco))(data) ?? '',
    [data, x, y]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(3, Math.round(innerWidth / 80)))
        .map((v) => ({ value: d3.timeFormat('%b')(v), offset: x(v) })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: `${v}°`, offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Difference chart comparing daily high temperatures in San Francisco and New York">
      <defs>
        <clipPath id={`${clipId}-above`}>
          <path d={areaTo.aboveNewYork} />
        </clipPath>
        <clipPath id={`${clipId}-below`}>
          <path d={areaTo.belowNewYork} />
        </clipPath>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {/* Each band is an area clipped to the half-plane on the far side of the other line. */}
        <path d={areaTo.belowSanFrancisco} fill={WARMER} clipPath={`url(#${clipId}-above)`} />
        <path d={areaTo.aboveSanFrancisco} fill={COOLER} clipPath={`url(#${clipId}-below)`} />
        <path d={line} fill="none" stroke="var(--text)" strokeWidth={1.25}
              strokeLinejoin="round" strokeLinecap="round" />
        {innerWidth >= 300 && (
          <g transform="translate(0,-12)" fontSize={11} fill="var(--muted)">
            <rect width={10} height={10} y={-9} fill={WARMER} />
            <text x={15} dy="-0.1em">San Francisco warmer</text>
            <rect x={155} width={10} height={10} y={-9} fill={COOLER} />
            <text x={170} dy="-0.1em">New York warmer</text>
          </g>
        )}
      </g>
    </svg>
  );
}
